method.pseudocode:
while true:
    working_memory.update(observe_environment())
    candidates = reason_and_retrieve(working_memory, long_term_memory)
    selected = select_action(candidates)
    if selected.kind == "grounding":
        working_memory.update(environment.step(selected))
    elif selected.kind == "learning":
        long_term_memory.write(selected)
